{
  "name": "kvhttp",
  "version": "1.0.0",
  "private": true,
  "type": "module",
  "description": "In-memory HTTP/1.1 key-value server",
  "scripts": {
    "build": "bash build.sh",
    "typecheck": "tsc",
    "test": "node --test test/"
  },
  "devDependencies": {
    "@types/node": "^26.6.10",
    "typescript": "^5.9.3"
  }
}

import type { Store } from './store.ts';

export interface Request {
  method: string;
  /** Request path without the query string. */
  path: string;
  body: Buffer;
}

export interface Response {
  status: number;
  headers: Record<string, string>;
  body: Buffer;
}

const KEY_PATTERN = /^[A-Za-z0-9_-]{1,64}$/;
const EMPTY = Buffer.alloc(0);

const respond = (status: number, body: Buffer = EMPTY, headers: Record<string, string> = {}): Response => ({
  status,
  headers,
  body,
});

const methodNotAllowed = (allowed: string): Response => respond(405, EMPTY, { Allow: allowed });

function health({ method }: Request): Response {
  if (method !== 'GET') return methodNotAllowed('GET');
  return respond(200, Buffer.from('ok'), { 'Content-Type': 'text/plain; charset=utf-8' });
}

function listKeys(store: Store, { method }: Request): Response {
  if (method !== 'GET') return methodNotAllowed('GET');
  return respond(200, Buffer.from(JSON.stringify(store.keys())), { 'Content-Type': 'application/json' });
}

function item(store: Store, key: string, { method, body }: Request): Response {
  if (!KEY_PATTERN.test(key)) return respond(400);
  switch (method) {
    case 'GET': {
      const value = store.lookup(key);
      return value === undefined ? respond(404) : respond(200, value, { 'Content-Type': 'application/octet-stream' });
    }
    case 'PUT':
      return respond(store.put(key, body) ? 201 : 200);
    case 'DELETE':
      return respond(store.delete(key) ? 204 : 404);
    default:
      return methodNotAllowed('GET, PUT, DELETE');
  }
}

/** Returns a request handler backed by `store`. */
export function makeHandler(store: Store): (req: Request) => Response {
  return (req) => {
    const { path } = req;
    if (path === '/health') return health(req);
    if (path === '/kv') return listKeys(store, req);
    if (path.startsWith('/kv/')) return item(store, path.slice(4), req);
    return respond(404);
  };
}

/** Entry point: `app <port>` serves the key-value API on 127.0.0.1. */
import http from 'node:http';
import { makeHandler, type Response } from './handler.ts';
import { Store } from './store.ts';

/** Largest accepted request body: 1 MiB values plus generous headroom. */
const MAX_BODY = 8 * 1024 * 1024;

class BodyTooLarge extends Error {}

function parsePort(arg: string | undefined): number | undefined {
  if (arg === undefined || !/^\d+$/.test(arg)) return undefined;
  const n = Number(arg);
  return n >= 1 && n <= 65535 ? n : undefined;
}

async function readBody(req: http.IncomingMessage): Promise<Buffer> {
  const declared = Number(req.headers['content-length'] ?? 0);
  if (declared > MAX_BODY) throw new BodyTooLarge();
  const chunks: Buffer[] = [];
  let size = 0;
  for await (const chunk of req as AsyncIterable<Buffer>) {
    size += chunk.length;
    if (size > MAX_BODY) throw new BodyTooLarge();
    chunks.push(chunk);
  }
  return Buffer.concat(chunks, size);
}

function send(res: http.ServerResponse, { status, headers, body }: Response): void {
  res.writeHead(status, { ...headers, 'Content-Length': body.length });
  res.end(body);
}

function main(): void {
  const port = parsePort(process.argv[2]);
  if (port === undefined) {
    console.error('usage: app <port>');
    process.exit(2);
  }

  const handle = makeHandler(new Store());
  const server = http.createServer(async (req, res) => {
    try {
      const body = await readBody(req);
      const path = (req.url ?? '/').split('?', 1)[0]!;
      send(res, handle({ method: req.method ?? 'GET', path, body }));
    } catch (err) {
      const status = err instanceof BodyTooLarge ? 413 : 500;
      if (!res.headersSent) send(res, { status, headers: { Connection: 'close' }, body: Buffer.alloc(0) });
      else res.destroy();
    }
  });

  server.listen({ host: '127.0.0.1', port, backlog: 1024 }, () => {
    console.log(`kvhttp listening on 127.0.0.1:${port}`);
  });
}

main();

/** In-memory key-value store. */
export class Store {
  readonly #entries = new Map<string, Buffer>();

  /** Stores `value` under `key`. Returns true if the key was new. */
  put(key: string, value: Buffer): boolean {
    const isNew = !this.#entries.has(key);
    this.#entries.set(key, value);
    return isNew;
  }

  /** Returns the value stored under `key`, or undefined. */
  lookup(key: string): Buffer | undefined {
    return this.#entries.get(key);
  }

  /** Removes `key`. Returns true if it was present. */
  delete(key: string): boolean {
    return this.#entries.delete(key);
  }

  /** Returns every key in ascending order. */
  keys(): string[] {
    // Keys are ASCII, so code-unit order is byte order.
    return [...this.#entries.keys()].sort();
  }
}

import assert from 'node:assert/strict';
import { test } from 'node:test';
import { makeHandler, type Request } from '../src/handler.ts';
import { Store } from '../src/store.ts';

const call = (h: ReturnType<typeof makeHandler>, method: string, path: string, body?: string) =>
  h({ method, path, body: Buffer.from(body ?? '') } satisfies Request);

test('crud', () => {
  const h = makeHandler(new Store());
  assert.equal(call(h, 'PUT', '/kv/a', 'hello').status, 201);
  assert.equal(call(h, 'GET', '/kv/a').body.toString(), 'hello');
  assert.equal(call(h, 'PUT', '/kv/a', 'world').status, 200);
  assert.equal(call(h, 'GET', '/kv/a').body.toString(), 'world');
  assert.equal(call(h, 'DELETE', '/kv/a').status, 204);
  assert.equal(call(h, 'GET', '/kv/a').status, 404);
  assert.equal(call(h, 'DELETE', '/kv/a').status, 404);
});

test('listing', () => {
  const h = makeHandler(new Store());
  for (const k of ['b', 'a', 'c']) call(h, 'PUT', `/kv/${k}`, k);
  const res = call(h, 'GET', '/kv');
  assert.equal(res.status, 200);
  assert.equal(res.headers['Content-Type'], 'application/json');
  assert.equal(res.body.toString(), '["a","b","c"]');
});

test('errors', () => {
  const h = makeHandler(new Store());
  for (const path of ['/kv/', '/kv/a/b', '/kv/bad.key', `/kv/${'a'.repeat(65)}`]) {
    assert.equal(call(h, 'GET', path).status, 400, path);
  }
  for (const path of ['/', '/nope', '/health/', '/kvx']) {
    assert.equal(call(h, 'GET', path).status, 404, path);
  }
  assert.equal(call(h, 'POST', '/health').status, 405);
  assert.equal(call(h, 'PUT', '/kv').status, 405);
  assert.equal(call(h, 'PATCH', '/kv/a').status, 405);
});
